import{_ as l,C as r,o as e,c as d,j as a,a as o,E as s,a2 as n}from"./chunks/framework.C21TwvGF.js";const B=JSON.parse(`{"title":"6-dars (Mentor). Code Review metodologiyasi, etikasi va Branch Protection","description":"","frontmatter":{"title":"6-dars (Mentor). Code Review metodologiyasi, etikasi va Branch Protection","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"week":{"n":2,"link":"/mentor/11-sinf/hafta-02/"},"g":6,"title":"Code Review metodologiyasi, etikasi va Branch Protection","lead":"Eng zo'r kod — bu bir kishi yozgan, lekin butun jamoaning aqli bilan sayqallangan koddir. Code Review nafaqat xatolarni ushlaydi, balki dasturchini tezroq o'stiradi. Ushbu darsda professional muloqot etikasi, \\"Nitpick vs Blocker\\", GitHub taklif kodi va asosiy tarmoqni qulflash (Branch Protection)ni o'rganamiz.","slide":"/slaydlar/11-sinf/hafta-02/dars-3.html","test":"/slaydlar/11-sinf/hafta-02/dars-3-test.html","student_link":"/11-sinf/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/11-sinf/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/11-sinf/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/11-sinf/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Pull Request (PR) madaniyati, PR shabloni va Merge konfliktlar","link":"/mentor/11-sinf/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/11-sinf/hafta-02/dars-3.md","filePath":"mentor/11-sinf/hafta-02/dars-3.md"}`),h={name:"mentor/11-sinf/hafta-02/dars-3.md"},u={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},k={class:"blk"},m={id:"_2-konspekt",tabindex:"-1"},c={class:"blk"},q={id:"_3-amaliy-topshiriqlar",tabindex:"-1"},b={class:"blk"},p={id:"_4-tezkor-nazorat-5-daqiqa",tabindex:"-1"},y={class:"blk"},v={id:"_5-xulosa-va-keyingi-darsga-ko-prik",tabindex:"-1"};function f(_,i,x,z,P,R){const t=r("Icon");return e(),d("div",null,[i[15]||(i[15]=a("p",null,[a("strong",null,"Hafta:"),o(" 2 · "),a("strong",null,"Davomiyligi:"),o(" 80 daqiqa · "),a("strong",null,"Turi:"),o(" nazariya + amaliyot · "),a("strong",null,"I-bob"),o(", 6-dars (umumiy 6–51)")],-1)),a("div",u,[a("h2",g,[s(t,{name:"file-text"}),i[0]||(i[0]=o(" 1. Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),i[2]||(i[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchi dasturiy ta&#39;minot muhandisligida Code Review madaniyatini, professional diff tahlilini, reviewer va author o&#39;rtasidagi muloqot etikasini, &quot;Nitpick vs Blocker&quot; farqini hamda GitHub Branch Protection qoidalarini amalda qo&#39;llashni o&#39;rganadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Code Review&#39;ning 3 ta asosiy maqsadini (xatolarni erta tutish, bilim almashish, arxitektura barqarorligi) tushuntiradi.</li><li>Konstruktiv sharh yozish etikasini (&quot;odamni emas, kodni tahlil qilish&quot;, taklif va savol berish) biladi.</li><li>Kritik xatolar (Blockers) bilan mayda maslahatlarni (Nitpicks) ajratadi.</li><li>GitHub&#39;dagi <code>Files changed</code> panelida inline sharhlar va bir bosishda qabul qilinuvchi <strong>suggestion blocks</strong> (<code>suggestion</code>) yozadi.</li><li>PR&#39;ga 3 xil yakuniy baho (Approve, Request Changes, Comment) berish mantig&#39;ini tushunadi.</li><li>GitHub repozitoriyasida <code>main</code> tarmog&#39;i uchun Branch Protection Rules (kamida 1 ta approve, to&#39;g&#39;ridan-to&#39;g&#39;ri push taqiqlash) o&#39;rnatadi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10</td><td>Takrorlash</td><td>5-dars (Pull Request, What/Why/How, merge turlari, konfliktlar)</td></tr><tr><td>10–30</td><td>Yangi mavzu 1</td><td>Code Review nima uchun kerak? Reviewer va Author etikasi</td></tr><tr><td>30–40</td><td>Yangi mavzu 2</td><td>Diff tahlili, Nitpicking vs Blocker, GitHub taklif kodi (suggestion)</td></tr><tr><td>40–45</td><td>Tanaffus</td><td></td></tr><tr><td>45–55</td><td>Yangi mavzu 3</td><td>GitHub Branch Protection: main tarmog&#39;ini qulflash</td></tr><tr><td>55–75</td><td>Amaliyot</td><td>Hamkasb kodi ustida review o&#39;tkazish, suggestion yozish va Branch Protection sozlash</td></tr><tr><td>75–80</td><td>Tezkor nazorat va xulosa</td><td>5 ta savol, 2-hafta yakuni</td></tr></tbody></table><hr>',5))]),a("div",k,[a("h2",m,[s(t,{name:"file-text"}),i[3]||(i[3]=o(" 2. Konspekt ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),i[5]||(i[5]=n('<h3 id="_2-1-takrorlash-10-daqiqa" tabindex="-1">2.1. Takrorlash (10 daqiqa) <a class="header-anchor" href="#_2-1-takrorlash-10-daqiqa" aria-label="Permalink to &quot;2.1. Takrorlash (10 daqiqa)&quot;">​</a></h3><ul><li>PR nima va nega unga dalil (skrinshot/log) qo&#39;shish kerak?</li><li>Squash and merge qanday ishlaydi?</li></ul><h3 id="_2-2-code-review-nima-va-nega-u-dasturchining-asosiy-o-sish-quroli" tabindex="-1">2.2. Code Review nima va nega u dasturchining asosiy o&#39;sish quroli? <a class="header-anchor" href="#_2-2-code-review-nima-va-nega-u-dasturchining-asosiy-o-sish-quroli" aria-label="Permalink to &quot;2.2. Code Review nima va nega u dasturchining asosiy o&#39;sish quroli?&quot;">​</a></h3><p><strong>Code Review</strong> — bu boshqa bir muhandis tomonidan yozilgan kodni asosiy tarmoqqa birlashtirishdan oldin sinchiklab o&#39;qib chiqish, tahlil qilish va fikr bildirish jarayonidir.</p><p>Code Review nima uchun kerak?</p><ol><li><strong>Xatolarni erta aniqlash:</strong> Hatto eng kuchli dasturchi ham charchaganida oddiy xatolarga yo&#39;l qo&#39;yadi. Boshqa odamning yangi nigohi xatoni darhol ilg&#39;aydi.</li><li><strong>Xavfsizlik (Security):</strong> Kodda ochiq qolgan parollar, SQL inyeksiya xavfi yoki ruxsatsiz kirish teshiklarini to&#39;sadi.</li><li><strong>Bilim almashish (Knowledge Sharing):</strong> Jamoaning har bir a&#39;zosi loyihaning boshqa qismlari qanday ishlayotganini bilib boradi. Yosh dasturchilar tajribali muhandislarning sharhlaridan eng tez o&#39;rganadi.</li><li><strong>Kod tozaligi (Code Maintainability):</strong> Loyihada yagona format va me&#39;moriy uslub saqlanadi.</li></ol><h3 id="_2-3-code-review-etikasi-muloqot-madaniyati" tabindex="-1">2.3. Code Review etikasi (Muloqot madaniyati) <a class="header-anchor" href="#_2-3-code-review-etikasi-muloqot-madaniyati" aria-label="Permalink to &quot;2.3. Code Review etikasi (Muloqot madaniyati)&quot;">​</a></h3><p>Code Review — bu kim aqlliroq ekanini isbotlash musobaqasi EMAS! Yomon muloqot jamoani parokanda qilishi mumkin.</p><p><strong>Asosiy qoidalar:</strong></p><ol><li><strong>Kodni tanqid qiling, shaxsni emas:</strong><ul><li>❌ Noto&#39;g&#39;ri: <em>&quot;Sen bu yerda juda xunuk va sekin kod yozgansan.&quot;</em></li><li>✅ To&#39;g&#39;ri: <em>&quot;Bu sikl katta ro&#39;yxatlarda sekinlashishi mumkin. Keling, buni lug&#39;at (hashmap) orqali O(1) tezlikka keltiramiz.&quot;</em></li></ul></li><li><strong>Buyruq bermang, savol bering va sabab keltiring:</strong><ul><li>❌ Noto&#39;g&#39;ri: <em>&quot;Bu funksiyani 3 ga bo&#39;l!&quot;</em></li><li>✅ To&#39;g&#39;ri: <em>&quot;Bu funksiya 80 qatordan oshib ketibdi. Uni testlash osonroq bo&#39;lishi uchun 2 ta kichik yordamchi funksiyaga ajratsak qanday qaraysiz?&quot;</em></li></ul></li><li><strong>Yaxshi yechimlarni ham maqtang:</strong><ul><li>Review faqat xato topishdan iborat emas. Agar hamkasbingiz chiroyli va nafis algoritm yozgan bo&#39;lsa: <em>&quot;Ajoyib yechim, menga juda yoqdi!&quot;</em> deb sharh qoldiring.</li></ul></li></ol><h3 id="_2-4-nitpicking-vs-blocker-pashshadan-fil-yasamang" tabindex="-1">2.4. Nitpicking vs Blocker (Pashshadan fil yasamang!) <a class="header-anchor" href="#_2-4-nitpicking-vs-blocker-pashshadan-fil-yasamang" aria-label="Permalink to &quot;2.4. Nitpicking vs Blocker (Pashshadan fil yasamang!)&quot;">​</a></h3><p>Reviewer har bir o&#39;zgarishning darajasini to&#39;g&#39;ri ajrata bilishi kerak:</p><ul><li><p><strong>Blocker (Kritik xato — Qat&#39;iy to&#39;siq):</strong></p><ul><li>Tizim qulashiga olib keluvchi xatolik;</li><li>Xavfsizlik zaifligi (masalan, token ochiq qolgan);</li><li>Biznes mantiq noto&#39;g&#39;ri ishlashi;</li><li>Testlar yo&#39;qligi.</li><li><em>Natija:</em> <code>Request changes</code> (tuzatmaguncha merge qilish taqiqlanadi!).</li></ul></li><li><p><strong>Nitpick (Mayda maslahat / Maydalashish):</strong></p><ul><li>O&#39;zgaruvchi nomini boshqacha atash;</li><li>Ortiqcha bitta bo&#39;sh qator;</li><li>Shaxsiy ta&#39;bga bog&#39;liq mayda uslub.</li><li><em>Qoida:</em> Sharh boshiga <code>nit:</code> yoki <code>ixtiyoriy:</code> deb yoziladi. Bu muallifning ixtiyorida qoladi va PR&#39;ni to&#39;xtatib turmasligi shart!</li></ul></li></ul><h3 id="_2-5-github-review-asboblari-va-taklif-kodi-suggestion" tabindex="-1">2.5. GitHub Review asboblari va Taklif kodi (Suggestion) <a class="header-anchor" href="#_2-5-github-review-asboblari-va-taklif-kodi-suggestion" aria-label="Permalink to &quot;2.5. GitHub Review asboblari va Taklif kodi (Suggestion)&quot;">​</a></h3><p>GitHub PR interfeysidagi <code>Files changed</code> bo&#39;limida:</p><ul><li>Qator ustiga kursor olib borib, <code>+</code> tugmasini bosish orqali aynan o&#39;sha qatorga sharh qoldiriladi.</li><li><strong>Taklif kodi (Code Suggestion):</strong> Sharh oynasidagi maxsus tugma orqali kod taklif qilish mumkin:</li></ul><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">```suggestion</span></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">def calculate_total(items):</span></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">    return sum(item.price for item in items)</span></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">```</span></span></code></pre></div><p>Muallif ushbu taklifni ko&#39;rganda, o&#39;z kompyuterida kod yozib o&#39;tirmasdan, GitHub&#39;dagi <strong>&quot;Commit suggestion&quot;</strong> tugmasini bitta bosish orqali taklifni to&#39;g&#39;ridan-to&#39;g&#39;ri o&#39;z branchiga commit qilib oladi!</p><p><strong>Review yakuni bo&#39;yicha 3 ta qaror:</strong></p><ol><li><code>Comment</code> — shunchaki savollar berish (tasdiqlamaydi ham, bloklamaydi ham).</li><li><code>Approve</code> — kod to&#39;liq talabga javob beradi, mergaga ruxsat.</li><li><code>Request changes</code> — jiddiy xatolar bor, qayta ishlab ko&#39;rsatish talab qilinadi.</li></ol><h3 id="_2-6-github-branch-protection-rules" tabindex="-1">2.6. GitHub Branch Protection Rules <a class="header-anchor" href="#_2-6-github-branch-protection-rules" aria-label="Permalink to &quot;2.6. GitHub Branch Protection Rules&quot;">​</a></h3><p>Jamoada hech kim (hatto jamoa sardori yoki loyiha egasi ham) xatolik bilan <code>main</code> tarmog&#39;ini buzib qo&#39;ymasligi uchun GitHub&#39;da himoya qoidalari o&#39;rnatiladi:</p><ul><li><code>Settings → Branches → Add branch ruleset / protection rule</code>: <ol><li><strong>Branch name pattern:</strong> <code>main</code></li><li><strong>Require a pull request before merging:</strong> to&#39;g&#39;ridan-to&#39;g&#39;ri <code>git push origin main</code> qilish butunlay bloklanadi!</li><li><strong>Require approvals:</strong> kamida 1 nafar (yoki 2 nafar) boshqa muhandis <code>Approve</code> bosmaguncha &quot;Merge&quot; tugmasi nofaol bo&#39;ladi.</li><li><strong>Require status checks to pass:</strong> avtomatlashtirilgan testlar (CI) muvaffaqiyatli o&#39;tmaguncha merge qilish taqiqlanadi.</li></ol></li></ul><hr>',24))]),a("div",c,[a("h2",q,[s(t,{name:"file-text"}),i[6]||(i[6]=o(" 3. Amaliy topshiriqlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar"'},"​",-1))]),i[8]||(i[8]=n('<h3 id="_1-topshiriq-konstruktiv-inline-sharh-yozish" tabindex="-1">1-topshiriq. Konstruktiv inline sharh yozish <a class="header-anchor" href="#_1-topshiriq-konstruktiv-inline-sharh-yozish" aria-label="Permalink to &quot;1-topshiriq. Konstruktiv inline sharh yozish&quot;">​</a></h3><p>Hamkasbingiz kodida quyidagi qatorni ko&#39;rdingiz: <code>sql = &quot;SELECT * FROM users WHERE name = &#39;&quot; + user_input + &quot;&#39;&quot;</code> Unga xavfsizlik (SQL Injection) bo&#39;yicha professional, konstruktiv va xushmuomala sharh matnini yozing.</p><p><strong>Yechim:</strong></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">Ushbu so&#39;rovda stringlarni to&#39;g&#39;ridan-to&#39;g&#39;ri qo&#39;shish (concatenation) SQL Injection zaifligiga olib kelishi mumkin. Foydalanuvchi ma&#39;lumotlari orqali bazani buzib kirmasliklari uchun parametrlangan so&#39;rovlardan (prepared statements) foydalanishni taklif qilaman:</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">```suggestion</span></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">cursor.execute(&quot;SELECT * FROM users WHERE name = %s&quot;, (user_input,))</span></span>\n<span class="line"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">```</span></span></code></pre></div><h3 id="_2-topshiriq-branch-protection-qoidalarini-sozlash" tabindex="-1">2-topshiriq. Branch Protection qoidalarini sozlash <a class="header-anchor" href="#_2-topshiriq-branch-protection-qoidalarini-sozlash" aria-label="Permalink to &quot;2-topshiriq. Branch Protection qoidalarini sozlash&quot;">​</a></h3><p>GitHub repozitoriyangizda <code>main</code> tarmog&#39;ini himoyalash qoidasini o&#39;rnating: to&#39;g&#39;ridan-to&#39;g&#39;ri push qilishni taqiqlang va PR orqali kamida 1 ta approve talab qiling.</p><p><strong>Yechim:</strong></p><ol><li>GitHub repoga kirish → <code>Settings</code> → chap menyudan <code>Branches</code>;</li><li><code>Add classic branch protection rule</code> tugmasini bosish;</li><li><code>Branch name pattern</code>: <code>main</code>;</li><li><code>Require a pull request before merging</code> katakchasini yoqish;</li><li><code>Require approvals</code>: 1 ta qilib belgilash;</li><li><code>Save changes</code> tugmasini bosish. <em>Natija:</em> Endi terminaldan <code>git push origin main</code> qilinsa, GitHub rad etadi: <code>remote: error: GH006: Protected branch update failed for refs/heads/main</code>.</li></ol><h3 id="_3-topshiriq-nitpick-va-blocker-tasnifi" tabindex="-1">3-topshiriq. Nitpick va Blocker tasnifi <a class="header-anchor" href="#_3-topshiriq-nitpick-va-blocker-tasnifi" aria-label="Permalink to &quot;3-topshiriq. Nitpick va Blocker tasnifi&quot;">​</a></h3><p>Quyidagi 4 ta muammoni &quot;Blocker&quot; yoki &quot;Nitpick&quot; toifalariga ajrating:</p><ol><li>API tokeni kod ichida ochiq yozilgan;</li><li>Funksiya argumenti nomi <code>x</code> deb atalgan, <code>user_count</code> deyilsa yaxshiroq bo&#39;lardi;</li><li>Login funksiyasida bo&#39;sh parol kiritilganda server 500 Internal Error berib qulaydi;</li><li>Qator oxirida ortiqcha 2 ta probel qolib ketgan.</li></ol><p><strong>Yechim:</strong></p><ul><li>1 va 3 — <strong>Blocker</strong> (xavfsizlik va server xatosi — tuzatish shart!).</li><li>2 va 4 — <strong>Nitpick</strong> (mayda uslubiy maslahat — ixtiyoriy, mergeni to&#39;xtatmaydi).</li></ul><hr>',14))]),a("div",b,[a("h2",p,[s(t,{name:"file-text"}),i[9]||(i[9]=o(" 4. Tezkor nazorat (5 daqiqa) ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-5-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat (5 daqiqa)"'},"​",-1))]),i[11]||(i[11]=n("<ol><li>Code Review jarayonining jamoa uchun asosiy 3 ta foydasi nima? <ul><li><strong>Javob:</strong> Xatolarni erta tutish, xavfsizlikni ta&#39;minlash va jamoada bilim/tajriba almashish.</li></ul></li><li>Code Review etikasidagi &quot;odamni emas, kodni baholash&quot; qoidasini qanday tushunasiz? <ul><li><strong>Javob:</strong> Shaxsiy ayblash va haqoratlardan qochib, faqat texnik sabab va takliflar asosida xolis fikr bildirish.</li></ul></li><li>&quot;Nitpick&quot; so&#39;zi nimani bildiradi va u &quot;Blocker&quot;dan nimasi bilan farq qiladi? <ul><li><strong>Javob:</strong> Nitpick — kichik uslubiy maslahat bo&#39;lib, u PR birlashishini to&#39;xtatmaydi; Blocker esa xavfli xato bo&#39;lib, tuzatilishi majburiy.</li></ul></li><li>GitHub da code suggestion bloki qanday afzallik beradi? <ul><li><strong>Javob:</strong> Muallifga tayyor to&#39;g&#39;rilangan kodni taklif qiladi va uni bitta tugma bilan repoga commit qilib olish imkonini beradi.</li></ul></li><li>Branch Protection Rules nima uchun kerak? <ul><li><strong>Javob:</strong> Asosiy tarmoqqa tasodifan yoki tekshirilmasdan xom kod push qilinishining oldini olish uchun.</li></ul></li></ol><hr>",2))]),a("div",y,[a("h2",v,[s(t,{name:"file-text"}),i[12]||(i[12]=o(" 5. Xulosa va keyingi darsga ko'prik ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#_5-xulosa-va-keyingi-darsga-ko-prik","aria-label":`Permalink to "<Icon name="file-text" /> 5. Xulosa va keyingi darsga ko'prik"`},"​",-1))]),i[14]||(i[14]=a("p",null,[o("2-hafta davomida biz tarmoqlanish arxitekturasi, Conventional Commits, Pull Request madaniyati, konfliktlarni yechish, Code Review etikasi va Branch Protection qoidalarini to'liq o'zlashtirdik. Siz endi yirik IT-kompaniyalarda talab qilinadigan professional jamoaviy madaniyatga egasiz! "),a("strong",null,"Keyingi hafta (3-hafta, 7–8 darslar):"),o(" Kod sifati va arxitekturasining cho'qqisi — "),a("strong",null,"Clean Code va SOLID tamoyillari"),o(" (SRP, OCP, LSP, ISP, DIP) bilan tanishamiz!")],-1))])])}const T=l(h,[["render",f]]);export{B as __pageData,T as default};
